<template>
  <div class="page-stack">
    <div class="page-heading"><div><div class="eyebrow">GOODS PROCUREMENT</div><h1>货品采购与库存作业</h1><p>采购确认、分批实收、待上架、上架与同仓移库</p></div><el-tooltip :content="canPurchase?'新建货品采购单':'当前账号没有货品采购写权限'"><span><el-button type="primary" :disabled="!canPurchase" @click="createVisible=true">新建货品采购单</el-button></span></el-tooltip></div>
    <el-card shadow="never">
      <el-tabs v-model="tab" @tab-change="load">
        <el-tab-pane label="采购单" name="purchases"/><el-tab-pane label="按库位库存" name="stock"/><el-tab-pane label="库存流水" name="flows"/>
      </el-tabs>
      <div v-if="tab!=='purchases'" class="toolbar"><el-select v-model="filterWarehouse" clearable placeholder="全部仓库" style="width:180px" @change="load"><el-option v-for="x in lookups.warehouses" :key="x.id" :label="x.warehouseName" :value="x.id"/></el-select><el-select v-model="filterGoods" clearable filterable placeholder="全部货品" style="width:260px" @change="load"><el-option v-for="x in lookups.goods" :key="x.id" :label="`${x.goodsCode} · ${x.goodsName}`" :value="x.id"/></el-select><el-button @click="load">刷新</el-button><el-button v-if="canPutaway" type="primary" @click="openAction('putaway')">上架</el-button><el-button v-if="canMove" type="primary" @click="openAction('move')">同仓移库</el-button></div>
      <el-table v-if="tab==='purchases'" :data="rows" v-loading="loading" stripe><el-table-column prop="poNo" label="采购单号" min-width="170"/><el-table-column prop="supplierName" label="供应商" min-width="140"/><el-table-column prop="warehouseName" label="采购仓库" min-width="140"><template #default="{row}">{{ row.warehouseName||'—' }}</template></el-table-column><el-table-column prop="trackingNo" label="快递单号" min-width="150"><template #default="{row}">{{ row.trackingNo||'—' }}</template></el-table-column><el-table-column prop="orderNo" label="供应商订单号" min-width="150"><template #default="{row}">{{ row.orderNo||'—' }}</template></el-table-column><el-table-column prop="status" label="采购状态" min-width="120"><template #default="{row}">{{ statusText(row.status) }}</template></el-table-column><el-table-column prop="expectedArrivalDate" label="预计到货日期" min-width="130"><template #default="{row}">{{ row.expectedArrivalDate||'—' }}</template></el-table-column><el-table-column prop="createdAt" label="创建时间" min-width="170"><template #default="{row}">{{ formatChinaDateTime(row.createdAt) }}</template></el-table-column><el-table-column label="操作" width="260" fixed="right"><template #default="{row}"><el-button link @click="openDetail(row.id)">查看明细</el-button><el-button v-if="canPurchase&&row.status==='DRAFT'" link type="primary" @click="openConfirm(row.id)">确认采购</el-button><el-button v-if="canReceive&&['CONFIRMED','PARTIALLY_RECEIVED'].includes(row.status)" link type="success" @click="openReceipt(row.id)">分批收货</el-button></template></el-table-column></el-table>
      <el-table v-else-if="tab==='stock'" :data="rows" v-loading="loading" stripe><el-table-column prop="warehouseCode" label="仓库"/><el-table-column prop="goodsCode" label="货品"/><el-table-column prop="goodsName" label="名称"/><el-table-column label="具体位置" min-width="300"><template #default="{row}"><LocationDisplay :location="row"/></template></el-table-column><el-table-column prop="locationTypeName" label="类型"/><el-table-column prop="availableQty" label="可拣数量"/><el-table-column prop="pendingPutawayQty" label="待上架"/><el-table-column prop="averageUnitCost" label="均价（人民币）"/></el-table>
      <el-table v-else :data="rows" v-loading="loading" stripe><el-table-column prop="createdAt" label="时间"><template #default="{row}">{{ formatChinaDateTime(row.createdAt) }}</template></el-table-column><el-table-column prop="documentId" label="单据 ID"/><el-table-column prop="flowType" label="类型"/><el-table-column prop="goodsCode" label="货品"/><el-table-column label="具体位置" min-width="300"><template #default="{row}"><LocationDisplay :location="row"/></template></el-table-column><el-table-column prop="availableDelta" label="可拣变化"/><el-table-column prop="pendingPutawayDelta" label="待上架变化"/><el-table-column prop="unitCostSnapshot" label="成本快照"/><el-table-column prop="operatorId" label="操作人 ID"/></el-table>
    </el-card>
    <el-dialog v-model="createVisible" title="新建货品采购单" width="850px"><el-form label-position="top"><el-form-item label="供应商"><el-select v-model="createForm.supplierId" filterable><el-option v-for="x in lookups.suppliers" :key="x.id" :label="x.supplierName" :value="x.id"/></el-select></el-form-item><el-form-item label="采购目标仓库"><el-select v-model="createForm.warehouseId"><el-option v-for="x in lookups.warehouses" :key="x.id" :label="x.warehouseName" :value="x.id"/></el-select></el-form-item><el-form-item label="预计到货"><el-date-picker v-model="createForm.expectedArrivalDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="快递单号"><el-input v-model="createForm.trackingNo"/></el-form-item><el-form-item label="供应商订单号"><el-input v-model="createForm.orderNo"/></el-form-item></el-form><el-table :data="createForm.items"><el-table-column label="仓库货品" min-width="280"><template #default="{row}"><el-select v-model="row.goodsId" filterable @change="suggest(row)"><el-option v-for="x in lookups.goods" :key="x.id" :label="`${x.goodsCode} · ${x.goodsName}`" :value="x.id"/></el-select></template></el-table-column><el-table-column label="数量"><template #default="{row}"><el-input-number v-model="row.quantity" :min="0.0001" :precision="4"/></template></el-table-column><el-table-column label="参考/建议单价"><template #default="{row}"><el-input-number v-model="row.suggestedPrice" :min="0" :precision="4"/></template></el-table-column><el-table-column label=""><template #default="{$index}"><el-button link type="danger" @click="createForm.items.splice($index,1)">删除</el-button></template></el-table-column></el-table><el-button @click="createForm.items.push({goodsId:null,quantity:1,suggestedPrice:0})">添加货品</el-button><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="createPurchase">创建</el-button></template></el-dialog>
    <el-dialog v-model="detailVisible" :title="`采购单明细 · ${detail?.poNo||''}`" width="900px"><el-descriptions v-if="detail" :column="2" border class="purchase-meta"><el-descriptions-item label="采购单号">{{ detail.poNo }}</el-descriptions-item><el-descriptions-item label="采购状态">{{ statusText(detail.status) }}</el-descriptions-item><el-descriptions-item label="供应商">{{ detail.supplierName||'—' }}</el-descriptions-item><el-descriptions-item label="采购仓库">{{ detail.warehouseName||'—' }}</el-descriptions-item><el-descriptions-item label="快递单号">{{ detail.trackingNo||'—' }}</el-descriptions-item><el-descriptions-item label="供应商订单号">{{ detail.orderNo||'—' }}</el-descriptions-item><el-descriptions-item label="预计到货日期">{{ detail.expectedArrivalDate||'—' }}</el-descriptions-item><el-descriptions-item label="创建时间">{{ formatChinaDateTime(detail.createdAt) }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.note||'—' }}</el-descriptions-item></el-descriptions><el-table :data="detail?.items||[]" style="margin-top:16px"><el-table-column prop="goodsCode" label="货品编码" min-width="130"/><el-table-column prop="goodsName" label="货品名称" min-width="160"/><el-table-column prop="unit" label="单位" width="90"/><el-table-column prop="orderedQty" label="采购数量" width="100"/><el-table-column prop="confirmedQty" label="确认数量" width="100"/><el-table-column prop="receivedQty" label="已收数量" width="100"/><el-table-column prop="suggestedPrice" label="参考单价（元）" width="120"/><el-table-column prop="totalAmount" label="采购金额（元）" width="130"/></el-table><template #footer><el-button @click="detailVisible=false">关闭</el-button></template></el-dialog>
    <el-dialog v-model="confirmVisible" title="确认采购货品" width="800px"><el-table :data="detail?.items||[]"><el-table-column prop="goodsCode" label="货品"/><el-table-column prop="orderedQty" label="订购"/><el-table-column label="确认数量"><template #default="{row}"><el-input-number v-model="row.confirmInput" :min="0" :precision="4"/></template></el-table-column><el-table-column label="超量原因"><template #default="{row}"><el-input v-model="row.reason"/></template></el-table-column></el-table><template #footer><el-button @click="confirmVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="confirmPurchase">确认</el-button></template></el-dialog>
    <el-dialog v-model="receiptVisible" :title="`分批收货 · ${detail?.poNo||''}`" width="min(960px, 96vw)">
      <el-descriptions :column="2" border><el-descriptions-item label="供应商">{{ detail?.supplierName }}</el-descriptions-item><el-descriptions-item label="所属仓库">{{ detail?.warehouseName }}</el-descriptions-item><el-descriptions-item label="快递单号">{{ detail?.trackingNo||'—' }}</el-descriptions-item><el-descriptions-item label="供应商订单号">{{ detail?.orderNo||'—' }}</el-descriptions-item></el-descriptions>
      <div class="receipt-toolbar"><span>勾选货品，展开填写数量、单价和库位。</span><div><el-button size="small" @click="selectAllReceivable">全选待收明细</el-button><el-button size="small" @click="receiptTable?.clearSelection()">取消全选</el-button></div></div>
      <el-alert title="优先选择本货品已绑定库位；未绑定货品可选空闲库位，收货成功后同步到仓库的货品位点绑定。待上架位记待上架库存，正式库位按收货并上架处理。" type="info" :closable="false" show-icon/>
      <el-alert v-if="!receiptLocations.length" title="没有可用收货库位，请先建立待上架位或未绑定货品的正式库位。" type="warning" :closable="false" show-icon/>
      <el-table ref="receiptTable" :data="detail?.items||[]" row-key="id" :expand-row-keys="receiptExpandedRows" @selection-change="receiptSelected=$event" style="margin-top:12px">
        <el-table-column type="selection" width="48" :selectable="canSelectReceiptLine"/>
        <el-table-column type="expand" width="48"><template #default="{row}"><div class="receipt-line-fields" v-if="canSelectReceiptLine(row)"><label>本次收货数量<el-input-number v-model="row.receiveQty" :min="0.0001" :precision="4" controls-position="right"/></label><label>实际单价（元）<el-input-number v-model="row.actualUnitPrice" :min="0" :precision="4" controls-position="right"/></label><label>收货库位<LocationSelect v-model="row.locationId" :locations="availableReceiptLocations(row)" placeholder="请选择库位" style="width:100%" receipt/><small v-if="!availableReceiptLocations(row).length">没有符合条件的库位，请在仓库中配置绑定或空闲库位。</small></label><label>超量原因<el-input v-model="row.overReceiptReason" placeholder="超出确认量时填写"/></label><label class="receipt-note">收货备注<el-input v-model="row.receiptNote" maxlength="1000" show-word-limit placeholder="选填，随收货记录保存"/></label></div><div v-else class="receipt-complete">该明细已全部收货</div></template></el-table-column>
        <el-table-column prop="goodsCode" label="货品编码" min-width="120"/><el-table-column prop="goodsName" label="货品名称" min-width="150"/><el-table-column prop="unit" label="单位" width="65"/><el-table-column prop="orderedQty" label="采购数量" width="90"/><el-table-column prop="confirmedQty" label="确认数量" width="90"/><el-table-column prop="receivedQty" label="已收数量" width="90"/><el-table-column label="待收数量" width="90"><template #default="{row}">{{ remainingReceiptQuantity(row) }}</template></el-table-column>
      </el-table>
      <template #footer><div class="receipt-footer"><span>已选 {{ receiptSelected.length }} 项 · 本次金额 ¥{{ selectedReceiptTotal.toFixed(4) }}</span><div><el-button :disabled="saving" @click="receiptVisible=false">取消</el-button><el-button :disabled="!canReceive||!receivableItems.length||saving" @click="receiveAll">一键全部按采购单收货</el-button><el-button type="primary" :disabled="!canReceive||!receiptSelected.length||!receiptLocations.length" :loading="saving" @click="receive(false)">确认收货已选货品</el-button></div></div></template>
    </el-dialog>
    <el-dialog v-model="actionVisible" :title="actionType==='putaway'?'上架确认':'同仓移库确认'" width="650px"><el-form label-position="top"><el-form-item label="仓库"><el-select v-model="action.warehouseId" @change="loadLocations('action')"><el-option v-for="x in lookups.warehouses" :key="x.id" :label="x.warehouseName" :value="x.id"/></el-select></el-form-item><el-form-item label="货品"><el-select v-model="action.goodsId" filterable @change="loadPutawayLocations"><el-option v-for="x in lookups.goods" :key="x.id" :label="`${x.goodsCode} · ${x.goodsName}`" :value="x.id"/></el-select></el-form-item><el-form-item label="来源位"><LocationSelect v-model="action.sourceLocationId" :locations="actionLocations.filter((v:any)=>actionType==='putaway'?v.locationType==='PENDING_PUTAWAY':!['PENDING_PUTAWAY','QUARANTINE'].includes(v.locationType))" /></el-form-item><el-form-item label="目标正式库位"><LocationSelect v-model="action.targetLocationId" :locations="actionType==='putaway'?putawayLocations:actionLocations.filter((v:any)=>!['PENDING_PUTAWAY','QUARANTINE'].includes(v.locationType))" :goods-id="actionType==='putaway'?action.goodsId:undefined" placeholder="先选择仓库和货品" /></el-form-item><el-form-item label="数量"><el-input-number v-model="action.quantity" :min="0.0001" :precision="4"/></el-form-item></el-form><template #footer><el-button @click="actionVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitAction">确认</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import LocationDisplay from '../components/LocationDisplay.vue'
import LocationSelect from '../components/LocationSelect.vue'
import { locationLabel } from '../utils/location'
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, type AuthUser } from '../api'
import { formatChinaDateTime } from '../utils/chinaTime'
import { useWarehouseRefresh } from '../utils/warehouseUpdates'

const root='/api/goods-procurement'
const statusText=(value?:string)=>({DRAFT:'待确认',CONFIRMED:'已确认待收货',PARTIALLY_RECEIVED:'部分收货',RECEIVED:'已全部收货',CLOSED:'已关闭'} as Record<string,string>)[value||'']||value||'—'
const props=defineProps<{user?:AuthUser}>()
const canPurchase=computed(()=>props.user?.permissions.includes('warehouse.goods.purchase')===true)
const canReceive=computed(()=>props.user?.permissions.includes('warehouse.goods.receive')===true)
const canPutaway=computed(()=>props.user?.permissions.includes('warehouse.goods.putaway')===true)
const canMove=computed(()=>props.user?.permissions.includes('warehouse.goods.move')===true)
const tab=ref('purchases'),rows=ref<any[]>([]),loading=ref(false),saving=ref(false)
const lookups=reactive<any>({suppliers:[],goods:[],warehouses:[]})
const filterWarehouse=ref<number>(),filterGoods=ref<number>()
const receivableItems=computed(()=>detail.value?.items?.filter((x:any)=>Number(x.confirmedQty)>Number(x.receivedQty))||[])
const createVisible=ref(false),detailVisible=ref(false),confirmVisible=ref(false),receiptVisible=ref(false),actionVisible=ref(false)
const detail=ref<any>(),createForm=reactive<any>({supplierId:null,warehouseId:null,expectedArrivalDate:'',trackingNo:'',orderNo:'',items:[{goodsId:null,quantity:1,suggestedPrice:0}]})
const receipt=reactive<{warehouseId:number|null}>({warehouseId:null})
const action=reactive<any>({warehouseId:null,goodsId:null,sourceLocationId:null,targetLocationId:null,quantity:1})
const receiptLocations=ref<any[]>([]),receiptTable=ref<any>(),receiptSelected=ref<any[]>([]),receiptExpandedRows=ref<number[]>([]),actionLocations=ref<any[]>([]),putawayLocations=ref<any[]>([]),actionType=ref<'putaway'|'move'>('putaway')
const selectedReceiptTotal=computed(()=>receiptSelected.value.reduce((total:number,row:any)=>total+Number(row.receiveQty||0)*Number(row.actualUnitPrice||0),0))
const pendingKeys:Record<string,string>={}
const pendingSignatures:Record<string,string>={}
function key(operation:string,payload:unknown){const signature=JSON.stringify(payload);if(pendingSignatures[operation]!==signature){pendingKeys[operation]=crypto.randomUUID();pendingSignatures[operation]=signature}return pendingKeys[operation]}
function committed(operation:string){delete pendingKeys[operation];delete pendingSignatures[operation]}
let loadVersion=0
async function loadRows(showLoading=true){const version=++loadVersion;if(showLoading)loading.value=true;try{const p=new URLSearchParams();if(filterWarehouse.value)p.set('warehouseId',String(filterWarehouse.value));if(filterGoods.value)p.set('goodsId',String(filterGoods.value));const path=tab.value==='purchases'?'/purchases':tab.value==='stock'?'/stock':'/flows';const result=await api<any>(`${root}${path}${p.size?'?'+p:''}`);if(version===loadVersion)rows.value=result.items}catch(e){if(version===loadVersion&&showLoading)ElMessage.error(error(e))}finally{if(version===loadVersion)loading.value=false}}
async function load(){await loadRows()}
useWarehouseRefresh(async()=>{if(!loading.value&&!saving.value&&tab.value!=='purchases')await loadRows(false)})
async function loadLocations(which:'receipt'|'action'){const warehouseId=which==='receipt'?receipt.warehouseId:action.warehouseId;if(which==='receipt')receiptLocations.value=[];else{action.goodsId=null;action.sourceLocationId=null;action.targetLocationId=null;putawayLocations.value=[]}if(!warehouseId)return;const data=await api<any>(`${root}/${which==='receipt'?'receipt-locations':'locations'}?warehouseId=${warehouseId}`);if(which==='receipt')receiptLocations.value=data.items;else actionLocations.value=data.items}
async function loadPutawayLocations(){action.targetLocationId=null;putawayLocations.value=[];if(actionType.value!=='putaway'||!action.warehouseId||!action.goodsId)return;try{putawayLocations.value=(await api<any>(`${root}/putaway-locations?warehouseId=${action.warehouseId}&goodsId=${action.goodsId}`)).items}catch(e){ElMessage.error(error(e))}}
function suggest(row:any){row.suggestedPrice=Number(lookups.goods.find((x:any)=>x.id===row.goodsId)?.referencePrice||0)}
function error(e:unknown){return e instanceof Error?e.message:'操作失败'}
async function openDetail(id:number){detail.value=undefined;try{detail.value=await api<any>(`${root}/purchases/${id}`);detailVisible.value=true}catch(e){ElMessage.error(error(e))}}
async function openConfirm(id:number){await openDetail(id);if(!detail.value)return;detail.value.items.forEach((x:any)=>{x.confirmInput=x.confirmedQty||x.orderedQty;x.reason='' });detailVisible.value=false;confirmVisible.value=true}
async function openReceipt(id:number){if(!canReceive.value)return ElMessage.warning('当前账号没有采购收货权限');try{detail.value=await api<any>(`${root}/purchases/${id}`);const lines=receivableItems.value;if(!lines.length)return ElMessage.info('该采购单没有待收货数量');lines.forEach((x:any)=>{x.receiveQty=remainingReceiptQuantity(x);x.actualUnitPrice=Number(x.suggestedPrice||0);x.overReceiptReason='';x.receiptNote='';x.locationId=null});receipt.warehouseId=detail.value.warehouseId;await loadLocations('receipt');lines.forEach((row:any)=>{const options=availableReceiptLocations(row);const own=options.filter((loc:any)=>loc.locationType!=='PENDING_PUTAWAY'&&Number(loc.assignedGoodsId)===Number(row.goodsId));const pending=options.filter((loc:any)=>loc.locationType==='PENDING_PUTAWAY');if(own.length===1)row.locationId=own[0].id;else if(!own.length&&pending.length===1)row.locationId=pending[0].id});receiptExpandedRows.value=detail.value.items.map((x:any)=>Number(x.id));receiptSelected.value=[];receiptVisible.value=true;await nextTick();selectAllReceivable()}catch(e){ElMessage.error(error(e))}}
function remainingReceiptQuantity(row:any){return Math.max(0,Math.round((Number(row.confirmedQty)-Number(row.receivedQty))*10000)/10000)}
function canSelectReceiptLine(row:any){return Number(row.confirmedQty)>Number(row.receivedQty)}
function availableReceiptLocations(row:any){const own=receiptLocations.value.filter((loc:any)=>loc.locationType!=='PENDING_PUTAWAY'&&Number(loc.assignmentCount)===1&&Number(loc.assignedGoodsId)===Number(row.goodsId));return receiptLocations.value.filter((loc:any)=>loc.locationType==='PENDING_PUTAWAY'||own.some((x:any)=>x.id===loc.id)||(!own.length&&Number(loc.assignmentCount)===0&&Number(loc.occupiedRows)===0&&Number(loc.openTasks)===0&&!receiptSelected.value.some((other:any)=>other.id!==row.id&&other.locationId===loc.id))).sort((a:any,b:any)=>Number(own.some((x:any)=>x.id===b.id))-Number(own.some((x:any)=>x.id===a.id)))}
function receiptLocationLabel(loc:any){return `${locationLabel(loc)}（${loc.locationType==='PENDING_PUTAWAY'?'共用待上架位':loc.assignedGoodsId!=null?'本货品已绑定 · 收货并上架':'空闲库位 · 收货时绑定'}）`}
function selectAllReceivable(){if(!receiptTable.value)return;receiptTable.value.clearSelection();receivableItems.value.forEach((row:any)=>receiptTable.value.toggleRowSelection(row,true))}
async function receiveAll(){selectAllReceivable();receivableItems.value.forEach((row:any)=>row.receiveQty=remainingReceiptQuantity(row));await nextTick();await receive(true)}
async function createPurchase(){saving.value=true;try{const result=await api<any>(`${root}/purchases`,{method:'POST',body:JSON.stringify({...createForm,idempotencyKey:key('create',createForm)})});committed('create');ElMessage.success(`已创建 ${result.poNo}`);createVisible.value=false;await load()}catch(e){ElMessage.error(error(e))}finally{saving.value=false}}
async function confirmPurchase(){saving.value=true;try{const items=detail.value.items.map((x:any)=>({itemId:x.id,confirmedQty:x.confirmInput,reason:x.reason}));await ElMessageBox.confirm(`${detail.value.poNo}\n${items.map((x:any)=>`${detail.value.items.find((line:any)=>line.id===x.itemId)?.goodsCode}：${x.confirmedQty}`).join('\n')}\n确认只更新采购确认数量，不增加库存。`,'确认采购数量');await api(`${root}/purchases/${detail.value.id}/confirm`,{method:'POST',body:JSON.stringify({idempotencyKey:key(`confirm-${detail.value.id}`,items),items})});committed(`confirm-${detail.value.id}`);ElMessage.success('已确认');confirmVisible.value=false;await load()}catch(e){if(e!=='cancel')ElMessage.error(error(e))}finally{saving.value=false}}
async function receive(all=false){
  if(saving.value)return
  if(!canReceive.value)return ElMessage.warning('当前账号没有采购收货权限')
  const lines=all?receivableItems.value:receiptSelected.value
  if(!lines.length)return ElMessage.warning('请勾选至少一条待收货明细')
  for(const line of lines){
    if(!line.locationId||!availableReceiptLocations(line).some((loc:any)=>loc.id===line.locationId))return ElMessage.warning(`请选择 ${line.goodsCode} 的有效收货库位`)
    if(!Number.isFinite(Number(line.receiveQty))||Number(line.receiveQty)<=0)return ElMessage.warning(`请填写 ${line.goodsCode} 的收货数量`)
    if(!Number.isFinite(Number(line.actualUnitPrice))||Number(line.actualUnitPrice)<0)return ElMessage.warning(`请填写 ${line.goodsCode} 的实际单价`)
    if(Number(line.receiveQty)>remainingReceiptQuantity(line)&&!line.overReceiptReason?.trim())return ElMessage.warning(`${line.goodsCode} 收货超过确认数量，请填写超量原因`)
  }
  saving.value=true
  try{
    const payload={warehouseId:receipt.warehouseId,receiveAll:all,items:lines.map((x:any)=>({itemId:x.id,locationId:x.locationId,quantity:x.receiveQty,actualUnitPrice:x.actualUnitPrice,overReceiptReason:x.overReceiptReason||'',note:x.receiptNote||''}))}
    const summary=lines.map((x:any)=>{const loc=receiptLocations.value.find((l:any)=>l.id===x.locationId);return `${x.goodsCode} · 数量 ${x.receiveQty} · 单价 ¥${Number(x.actualUnitPrice).toFixed(4)}\n库位：${loc?receiptLocationLabel(loc):'—'} · 金额 ¥${(Number(x.receiveQty)*Number(x.actualUnitPrice)).toFixed(4)}`}).join('\n\n')
    await ElMessageBox.confirm(`采购单：${detail.value.poNo}\n供应商：${detail.value.supplierName}\n仓库：${detail.value.warehouseName}\n\n${summary}\n\n确认后一次提交所选明细及新增库位绑定。`,all?'全部按采购单确认收货':'确认勾选货品收货',{confirmButtonText:'确认收货',cancelButtonText:'返回核对'})
    const operation=`receive-${detail.value.id}`
    const result=await api<any>(`${root}/purchases/${detail.value.id}/receipts`,{method:'POST',body:JSON.stringify({...payload,idempotencyKey:key(operation,payload)})})
    committed(operation)
    ElMessage.success(`已收货 ${result.items.length} 项，${statusText(result.status)}；新增绑定已同步至仓库货品位点绑定`)
    receiptVisible.value=false
    await load()
  }catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(error(e))}finally{saving.value=false}
}
function openAction(type:'putaway'|'move'){actionType.value=type;action.targetLocationId=null;putawayLocations.value=[];actionVisible.value=true;if(type==='putaway')void loadPutawayLocations()}
async function submitAction(){if(saving.value)return;if(!action.warehouseId||!action.goodsId||!action.sourceLocationId||!action.targetLocationId)return ElMessage.warning('请选择仓库、货品、来源位和目标位');if(actionType.value==='putaway'&&!putawayLocations.value.some((x:any)=>x.id===action.targetLocationId))return ElMessage.warning('请选择本货品已绑定位或符合条件的空闲位');saving.value=true;try{const warehouse=lookups.warehouses.find((x:any)=>x.id===action.warehouseId);const goods=lookups.goods.find((x:any)=>x.id===action.goodsId);const source=actionLocations.value.find((x:any)=>x.id===action.sourceLocationId);const target=(actionType.value==='putaway'?putawayLocations.value:actionLocations.value).find((x:any)=>x.id===action.targetLocationId);const binds=actionType.value==='putaway'&&Number(target?.assignmentCount)===0;await ElMessageBox.confirm(`仓库：${warehouse?.warehouseName||'—'}\n货品：${goods?.goodsCode||'—'}\n来源位：${locationLabel(source)}\n目标位：${locationLabel(target)}${binds?'（完成上架时绑定本货品）':''}\n数量：${action.quantity}\n同仓作业保持仓库总量不变。`,'提交库存作业');const result=await api<any>(`${root}/${actionType.value==='putaway'?'putaway':'moves'}`,{method:'POST',body:JSON.stringify({...action,idempotencyKey:key(actionType.value,action)})});committed(actionType.value);ElMessage.success(`已生成作业单 #${result.documentId}${result.bindingCreated?'；空闲位已同步绑定本货品':''}`);actionVisible.value=false;await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(error(e))}finally{saving.value=false}}
onMounted(async()=>{try{Object.assign(lookups,await api<any>(`${root}/lookups`));await load()}catch(e){ElMessage.error(error(e))}})
</script>
<style scoped>
.receipt-toolbar,.receipt-footer{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:16px 0}
.receipt-toolbar>span,.receipt-footer>span{color:#606266;font-size:13px}
.receipt-line-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px 24px;padding:18px 28px;background:#f7f9fc}
.receipt-line-fields label{display:flex;flex-direction:column;gap:8px;color:#404650;font-size:13px}
.receipt-line-fields :deep(.el-input-number){width:100%}
.receipt-note{grid-column:1/-1}.receipt-line-fields small{color:#b45309}.receipt-complete{padding:18px 28px;color:#909399}
.receipt-footer{margin:0;text-align:left}
@media(max-width:680px){.receipt-line-fields{grid-template-columns:1fr;padding:14px}.receipt-note{grid-column:auto}}
</style>
